window.AROUND_TOWN=[{"n":1,"week":21,"title":"Going Shopping","group":0,"level":"B1","setting":"Khalid is shopping for a jacket. Mark, a salesman, offers to help.","setting_ar":"خالد في متجر ملابس يبحث عن جاكيت، والبائع مارك يعرض عليه المساعدة.","speakers":["Mark","Khalid"],"pre":["ماذا تقول للبائع إذا أردت أن تتفرّج فقط دون شراء؟","هل تجرّب الملابس قبل شرائها؟ ولماذا؟"],"idioms":[{"e":"just browsing","m":"just browsing","ar":"أتفرّج فقط دون نيّة شراء أكيدة","ex":"No, thank you. I'm just browsing."},{"e":"come in","m":"come in","ar":"يتوفّر بلون أو مقاس معيّن","ex":"Do these shoes come in black?"},{"e":"sold out","m":"sold out","ar":"نفدت الكمية كلها","ex":"The tickets for the match were sold out in one hour."},{"e":"in stock","m":"in stock","ar":"متوفّر في المتجر للبيع","ex":"Sorry, this phone isn't in stock right now."},{"e":"marked down","m":"marked down","ar":"مُخفَّض السعر","ex":"The bag was marked down from 200 to 120 riyals."},{"e":"pricey","m":"pricey","ar":"غالٍ (عامية)","ex":"That café is nice, but it's a bit pricey."},{"e":"try on","m":"try it on","ar":"يجرّب لباساً ليعرف مقاسه","ex":"Can I try on these shoes in a bigger size?"},{"e":"run small","m":"runs small","ar":"مقاسه أصغر من المعتاد","ex":"This brand runs small, so take a larger size."},{"e":"take my word for it","m":"Take my word for it","ar":"صدّقني","ex":"Take my word for it, this book is great."},{"e":"hold off","m":"hold off","ar":"يؤجّل ويتريّث","ex":"Let's hold off on buying a car until next year."}],"keywords":[],"lines":[["Mark","Hi there! Can I help you find anything?"],["Khalid","Thanks, I'm just browsing for now."],["Mark","No problem. I'm Mark, if you need me."],["Khalid","Actually, does this jacket come in dark blue?"],["Mark","It did, but the blue ones are sold out. We can't keep them in stock."],["Khalid","That's too bad. Do you have any jackets on sale?"],["Mark","Yes. This grey one was ninety dollars. Now it's marked down to forty-five."],["Khalid","That's still a little pricey for a student, but can I try it on?"],["Mark","Of course. The fitting room is on your left. ... So, how is it?"],["Khalid","It's a bit tight across the shoulders."],["Mark","That style runs small. Here's the next size up."],["Khalid","This one feels better, but the sleeves are long, aren't they?"],["Mark","Not at all. It looks great on you. Take my word for it."],["Khalid","Thanks, but I think I'll hold off until the weekend. I want to compare prices first."]],"quiz":[{"q":"What colour did Khalid want?","options":["Grey","Dark blue","Black"],"answer":1,"why":"سأل خالد: does this jacket come in dark blue?"},{"q":"How much is the grey jacket now?","options":["Forty-five dollars","Ninety dollars","Fifty-four dollars"],"answer":0,"why":"كان سعره تسعين دولاراً ثم خُفِّض إلى خمسة وأربعين."},{"q":"Why did Mark bring a bigger size?","options":["Khalid wanted a black one","The bigger one was cheaper","The style runs small"],"answer":2,"why":"قال مارك: That style runs small، أي أن مقاسه صغير."},{"q":"In the dialogue, \"pricey\" means:","options":["cheap","expensive","comfortable"],"answer":1,"why":"pricey كلمة عامية بمعنى غالٍ."},{"q":"\"I'll hold off\" means Khalid will:","options":["wait before he decides","buy the jacket now","return the jacket"],"answer":0,"why":"hold off يعني يؤجّل، فخالد سينتظر ليقارن الأسعار."}],"post":["Do you prefer shopping in stores or online? Why?","What do you do when something you want is sold out?","Tell me about something good you bought on sale."],"tip":"إذا اقترب منك البائع ولا تريد مساعدة فقل بلطف: I'm just browsing, thanks. وهي عبارة مهذبة جداً ومنتشرة."},{"n":2,"week":22,"title":"Returning an Item","group":0,"level":"B1","setting":"Khalid's new headphones don't work. He takes them back to the store.","setting_ar":"سمّاعات خالد الجديدة لا تعمل، فيعيدها إلى المتجر.","speakers":["Tim","Khalid"],"pre":["هل أرجعت سلعة إلى متجر من قبل؟ ماذا حدث؟","ما الذي تحتاجه عادةً لإرجاع سلعة: الفاتورة، أم الكرتون، أم كلاهما؟"],"idioms":[{"e":"to the letter","m":"to the letter","ar":"بدقة تامة، حرفاً بحرف","ex":"I followed the recipe to the letter."},{"e":"take a crack at","m":"take a crack at it","ar":"يحاول تجربة شيء أو إصلاحه","ex":"Let me take a crack at this math problem."},{"e":"be my guest","m":"Be my guest","ar":"تفضّل، لا مانع عندي","ex":"\"Can I use your pen?\" \"Be my guest.\""},{"e":"steer clear of","m":"steer clear of","ar":"يتجنّب ويبتعد عن","ex":"Steer clear of that road. It's always busy."},{"e":"let alone","m":"let alone","ar":"فضلاً عن، ناهيك عن","ex":"I can't cook rice, let alone kabsa."},{"e":"even exchange","m":"even exchange","ar":"استبدال بسلعة بالسعر نفسه دون دفع فرق","ex":"The shirt was too small, so I made an even exchange."},{"e":"work out","m":"work out","ar":"ينجح ويكون مناسباً","ex":"If the new plan doesn't work out, we'll try another one."}],"keywords":[],"lines":[["Khalid","Hi. I bought these headphones here two days ago, and the left side isn't working."],["Tim","Sorry to hear that. Did you charge them and connect them to your phone?"],["Khalid","Yes. I followed the instructions to the letter."],["Tim","Do you mind if I take a crack at it?"],["Khalid","Be my guest."],["Tim","Hmm. You're right. There's no sound on the left. Would you like a new pair of the same model?"],["Khalid","No, thanks. My friend had the same problem with his. I'll steer clear of this model."],["Tim","I understand. One broken pair is annoying, let alone two."],["Khalid","Exactly. Can I get my money back?"],["Tim","Sure. Or you can make an even exchange for these. They cost the same, and people love them."],["Khalid","Can I listen to them first?"],["Tim","Of course. ... What do you think?"],["Khalid","The sound is great. OK, I'll take them."],["Tim","Great. If they don't work out, just bring them back within thirty days with your receipt."]],"quiz":[{"q":"What was wrong with the headphones?","options":["The battery was missing","They were too big","The left side had no sound"],"answer":2,"why":"قال خالد: the left side isn't working."},{"q":"Why doesn't Khalid want the same model again?","options":["It is too expensive","His friend had the same problem","He doesn't like the colour"],"answer":1,"why":"قال إن صديقه واجه المشكلة نفسها مع سماعاته."},{"q":"How long does Khalid have to return the new headphones?","options":["Thirty days","Seven days","One year"],"answer":0,"why":"قال تيم: within thirty days with your receipt."},{"q":"\"Be my guest\" means:","options":["Come to my house","I am a visitor","Please, go ahead"],"answer":2,"why":"Be my guest تعني «تفضّل، لا مانع»."},{"q":"\"steer clear of\" means:","options":["drive carefully","avoid","clean"],"answer":1,"why":"steer clear of يعني يتجنّب."}],"post":["Have you ever returned something to a store? What was the problem?","Is it easy to return things in shops in your city?","What do you check before you buy electronics?"],"tip":"عبارة Be my guest جواب لطيف عندما يستأذنك أحد: Can I try? — Be my guest. أي: تفضّل."},{"n":3,"week":23,"title":"Making a Deal","group":0,"level":"B1","setting":"Khalid wants to buy a used bicycle from Mike, who put an ad online.","setting_ar":"خالد يريد شراء درّاجة مستعملة من مايك الذي نشر إعلاناً على الإنترنت.","speakers":["Mike","Khalid"],"pre":["هل تحب المفاصلة في السعر؟ متى تفاصل ومتى لا؟","ماذا تفحص قبل أن تشتري شيئاً مستعملاً؟"],"idioms":[{"e":"in mint condition","m":"in mint condition","ar":"بحالة ممتازة كأنه جديد","ex":"My father's old car is still in mint condition."},{"e":"a steal","m":"a steal","ar":"صفقة رخيصة جداً، لقطة","ex":"Only 50 riyals for these shoes? That's a steal!"},{"e":"haggle","m":"haggle","ar":"يفاصل في السعر","ex":"In the old market, people often haggle over prices."},{"e":"money is tight","m":"money is tight","ar":"المال قليل هذه الفترة","ex":"Money is tight this month, so I'll cook at home."},{"e":"a lemon","m":"a lemon","ar":"سلعة رديئة كثيرة الأعطال","ex":"Don't buy that car. It's a lemon."},{"e":"split the difference","m":"split the difference","ar":"نقسم الفرق بيننا ونلتقي في المنتصف","ex":"You say 100, I say 80. Let's split the difference: 90."},{"e":"you've got a deal","m":"You've got a deal","ar":"اتفقنا","ex":"\"I'll pay 90.\" \"You've got a deal.\""},{"e":"give someone a ring","m":"give me a ring","ar":"يتصل به هاتفياً","ex":"Give me a ring when you arrive."}],"keywords":[],"lines":[["Mike","Hello?"],["Khalid","Hi, I'm calling about the bike in your ad. Is it still available?"],["Mike","Yes, it is. It's in mint condition. I only rode it a few times."],["Khalid","Great. Can I come and see it today?"],["Mike","Sure. ... Here it is. Do you want to ride it around the block first?"],["Khalid","Yes, please. ... It rides really well. How much are you asking?"],["Mike","Two hundred dollars. At that price, it's a steal."],["Khalid","I don't want to haggle, but money is tight for me this summer. Would you take one fifty?"],["Mike","One fifty? That's too low. It's a good bike, not a lemon."],["Khalid","I know it is. How about we split the difference? One seventy-five."],["Mike","You've got a deal."],["Khalid","Can I pay you tomorrow? My cousin will bring me here with the money."],["Mike","OK, but another buyer is interested, so give me a ring before ten if you're coming."]],"quiz":[{"q":"How did Khalid find out about the bike?","options":["From an ad","From his cousin","In a bike shop"],"answer":0,"why":"قال: I'm calling about the bike in your ad."},{"q":"What is the final price?","options":["$150","$200","$175"],"answer":2,"why":"طلب مايك 200 وعرض خالد 150، فقسما الفرق: 175."},{"q":"Why must Khalid call before ten?","options":["Mike starts work at ten","Another buyer is interested","The shop closes at ten"],"answer":1,"why":"قال مايك إن مشترياً آخر مهتم بالدراجة."},{"q":"Here, \"a lemon\" means:","options":["a product that often breaks","a yellow bike","a low price"],"answer":0,"why":"lemon في الشراء تعني سلعة رديئة كثيرة الأعطال."},{"q":"\"Money is tight\" means Khalid:","options":["has a lot of money","lost his wallet","doesn't have much money"],"answer":2,"why":"money is tight تعني أن المال قليل هذه الفترة."}],"post":["Do people haggle in markets in your town? Where?","What is the best deal you have ever made?","Would you buy a used phone? Why or why not?"],"tip":"لتفاصل بأدب ابدأ بـ I don't want to haggle, but... ثم اعرض حلاً وسطاً: How about we split the difference?"},{"n":4,"week":24,"title":"Buying a Phone Plan","group":0,"level":"B1","setting":"Khalid needs a phone plan for his two-month summer course. Eric works at the phone store.","setting_ar":"خالد يحتاج باقة جوال لدورته الصيفية مدة شهرين، وإريك موظف في متجر الاتصالات.","speakers":["Eric","Khalid"],"pre":["هل تقرأ العقود والشروط قبل أن توقّع أو توافق؟","هل يستحق تأمين الجوال ثمنه في رأيك؟"],"idioms":[{"e":"sign up for","m":"sign up for","ar":"يشترك في","ex":"I want to sign up for the summer football club."},{"e":"up front","m":"up front","ar":"مُقدَّماً، قبل الحصول على الخدمة","ex":"You have to pay the first month up front."},{"e":"peace of mind","m":"peace of mind","ar":"راحة البال والاطمئنان","ex":"A spare key gives me peace of mind."},{"e":"pay through the nose","m":"pay through the nose","ar":"يدفع مبلغاً باهظاً جداً","ex":"Tourists often pay through the nose for taxis."},{"e":"a no-brainer","m":"a no-brainer","ar":"قرار سهل وواضح لا يحتاج تفكيراً","ex":"Free breakfast with the room? That's a no-brainer."},{"e":"read the fine print","m":"read the fine print","ar":"يقرأ الشروط الصغيرة بدقة","ex":"Always read the fine print before you sign."},{"e":"sleep on it","m":"sleep on it","ar":"يؤجّل القرار ليفكر فيه حتى الغد","ex":"It's a big decision. Let me sleep on it."}],"keywords":[],"lines":[["Eric","Welcome! Are you looking for a phone plan?"],["Khalid","Yes. I'm here for two months, so I need something simple."],["Eric","Easy. You can sign up for our monthly plan. It's thirty dollars, with unlimited calls and texts."],["Khalid","Do I have to pay for both months up front?"],["Eric","No, you pay one month at a time. Would you also like our phone protection plan? It's eight dollars a month."],["Khalid","What does it cover?"],["Eric","If you drop your phone or it gets wet, we repair it for free. It gives you peace of mind."],["Khalid","Are repairs expensive here?"],["Eric","Very. Without the plan, you pay through the nose for a new screen."],["Khalid","It sounds like a no-brainer, but I want to read the fine print first."],["Eric","Smart. Here's the contract. Take your time."],["Khalid","Thanks. Actually, I'd like to sleep on it. Can I add the plan tomorrow?"],["Eric","Sure. You have fourteen days to add it."]],"quiz":[{"q":"How long is Khalid staying?","options":["Two weeks","Two months","One year"],"answer":1,"why":"قال: I'm here for two months."},{"q":"How much is the protection plan?","options":["Eight dollars a month","Thirty dollars a month","Fourteen dollars"],"answer":0,"why":"قال إريك: It's eight dollars a month."},{"q":"What will Khalid do before he decides?","options":["Call his father","Buy a new phone","Read the contract and think overnight"],"answer":2,"why":"أراد قراءة الشروط ثم قال: I'd like to sleep on it."},{"q":"\"pay through the nose\" means:","options":["pay by phone","pay much too much","pay later"],"answer":1,"why":"pay through the nose تعني يدفع مبلغاً باهظاً."},{"q":"\"up front\" means:","options":["before you get the service","at the end","in cash only"],"answer":0,"why":"up front تعني مقدَّماً."}],"post":["Which phone company do you use, and are you happy with it?","Do you read the fine print before you agree to an app's terms?","When was the last time you had to sleep on a decision?"],"tip":"عبارة Let me sleep on it طريقة مهذبة لتقول للبائع «سأفكر وأرد عليك» دون أن ترفض."},{"n":5,"week":25,"title":"Ordering at a Restaurant","group":1,"level":"B1","setting":"Khalid and his cousin Saad are having dinner at a busy restaurant. Tony is their waiter.","setting_ar":"خالد وابن عمه سعد يتناولان العشاء في مطعم مزدحم، وتوني هو النادل.","speakers":["Tony","Khalid"],"pre":["ماذا تطلب عادةً عندما تزور مطعماً لأول مرة؟","كيف تطلب طعاماً بدون مكوّن لا تحبه؟"],"idioms":[{"e":"I'll be right with you","m":"I'll be right with you","ar":"سآتيك حالاً","ex":"Please take a seat. I'll be right with you."},{"e":"Can I start you off with...?","m":"Can I start you off with","ar":"هل أبدأ لكم بـ... (أول الطلب)","ex":"Can I start you off with some soup?"},{"e":"the best of both worlds","m":"the best of both worlds","ar":"تجمع ميزتي الخيارين معاً","ex":"I live near the sea and the mountains: the best of both worlds."},{"e":"on the side","m":"on the side","ar":"في صحن جانبي منفصل","ex":"Can I have the sauce on the side, please?"},{"e":"hold the...","m":"hold the onions","ar":"بدون... (عند طلب الطعام)","ex":"A chicken sandwich, please, and hold the tomatoes."},{"e":"hold-up","m":"hold-up","ar":"تأخير، سبب التأخير","ex":"Sorry for the hold-up. The printer stopped working."},{"e":"flag down","m":"flag me down","ar":"يلوّح لشخص ليلفت انتباهه","ex":"We flagged down a taxi on the corner."}],"keywords":[],"lines":[["Tony","Hi, guys. I'll be right with you. ... OK, thanks for waiting. Can I start you off with something to drink?"],["Khalid","Two orange juices, please."],["Tony","Coming right up. Are you ready to order?"],["Khalid","I can't decide between the chicken sandwich and the salad."],["Tony","Get the chicken salad. It's the best of both worlds."],["Khalid","Good idea. Can I have the dressing on the side?"],["Tony","Sure. And for your friend?"],["Khalid","My cousin wants the fish burger, but please hold the onions."],["Tony","No problem. Fries or rice with that?"],["Khalid","Fries, please. ... Excuse me, what's the hold-up? We ordered thirty minutes ago."],["Tony","I'm so sorry. The kitchen is very busy tonight. I saw you trying to flag me down. Your food is coming out now."],["Khalid","Thank you. We're really hungry!"]],"quiz":[{"q":"What did Khalid order for himself?","options":["A fish burger","A chicken sandwich","Chicken salad"],"answer":2,"why":"نصحه توني بـ chicken salad فوافق."},{"q":"What doesn't Saad want in his burger?","options":["Fries","Onions","Juice"],"answer":1,"why":"قال خالد: hold the onions، أي بدون بصل."},{"q":"Why was the food late?","options":["The kitchen was very busy","The waiter forgot","The restaurant was closing"],"answer":0,"why":"قال توني: The kitchen is very busy tonight."},{"q":"\"flag down\" means:","options":["put up a flag","sit down","wave to get someone's attention"],"answer":2,"why":"flag down يعني يلوّح لشخص ليلفت انتباهه."},{"q":"\"What's the hold-up?\" means:","options":["Who is holding it?","Why is there a delay?","Can you hold this?"],"answer":1,"why":"hold-up تعني تأخيراً."}],"post":["What is your favourite restaurant, and what do you order there?","What do you do when your food takes too long?","Is there a food you always ask them to hold?"],"tip":"لتطلب طعاماً بدون شيء قل: hold the + المكوّن، مثل: hold the onions = بدون بصل. وهي عبارة يفهمها كل النُّدُل."},{"n":6,"week":26,"title":"A Problem with the Food","group":1,"level":"B1","setting":"Khalid's steak comes out burnt. He politely tells the waiter, Tom.","setting_ar":"شريحة اللحم التي طلبها خالد وصلت محترقة، فيخبر النادل توم بأدب.","speakers":["Tom","Khalid"],"pre":["كيف تشتكي في مطعم دون أن تكون غير مهذب؟","ماذا تفعل ببقية الطعام إذا لم تُنهِه؟"],"idioms":[{"e":"burnt to a crisp","m":"burnt to a crisp","ar":"محترق تماماً","ex":"I forgot the bread in the oven. It's burnt to a crisp."},{"e":"You bet","m":"You bet","ar":"أكيد، بكل سرور","ex":"\"Can you help me?\" \"You bet!\""},{"e":"pet peeve","m":"pet peeve","ar":"شيء صغير يزعجك كثيراً","ex":"People who talk in the cinema are my pet peeve."},{"e":"still working on it","m":"still working on it","ar":"ما زلت آكل منه، لم أنتهِ","ex":"\"Can I take your plate?\" \"No, I'm still working on it.\""},{"e":"box it up","m":"box it up","ar":"يضعه في علبة لتأخذه","ex":"The pizza was big, so we asked them to box it up."},{"e":"I'm stuffed","m":"stuffed","ar":"شبعان جداً","ex":"No more rice for me, thanks. I'm stuffed."},{"e":"leftovers","m":"leftovers","ar":"بقايا الطعام","ex":"We had the leftovers for lunch the next day."},{"e":"all set","m":"all set","ar":"جاهز، لا أحتاج شيئاً آخر","ex":"\"Do you need anything else?\" \"No, I'm all set.\""},{"e":"on the house","m":"on the house","ar":"مجاناً على حساب المطعم","ex":"The tea was on the house."}],"keywords":[],"lines":[["Tom","How is everything here?"],["Khalid","Actually, my steak is burnt to a crisp. I asked for it medium."],["Tom","I'm so sorry. I'll ask the chef to make you a new one right away."],["Khalid","Thank you. And my cousin's soup is cold. Could you warm it up, please?"],["Tom","You bet. I'll be right back."],["Khalid","Thanks. Cold soup is my cousin's pet peeve."],["Tom","... Here you go. How's the new steak?"],["Khalid","Perfect, thanks."],["Tom","Are you still working on it, or can I take your plate?"],["Khalid","I'm still working on it, but I can't finish it. Could you box it up for me?"],["Tom","Sure. Can I interest you in dessert? Our apple pie is famous."],["Khalid","No, thanks. I'm stuffed. The leftovers will be my lunch tomorrow."],["Tom","Are you all set, then?"],["Khalid","Yes, we're all set. Just the check, please."],["Tom","And because of the problem, your steak is on the house tonight."]],"quiz":[{"q":"What was wrong with the steak?","options":["It was burnt","It was too small","It was cold"],"answer":0,"why":"قال خالد: burnt to a crisp، أي محترقة تماماً."},{"q":"What was wrong with the soup?","options":["It was too salty","It was the wrong soup","It was cold"],"answer":2,"why":"قال خالد إن الشوربة باردة."},{"q":"What will Khalid do with the leftovers?","options":["Give them to Tom","Eat them for lunch tomorrow","Leave them on the table"],"answer":1,"why":"قال: The leftovers will be my lunch tomorrow."},{"q":"\"I'm stuffed\" means:","options":["I'm very full","I'm bored","I'm tired"],"answer":0,"why":"stuffed تعني شبعان جداً."},{"q":"\"on the house\" means:","options":["on the roof","delivered to your home","free, paid by the restaurant"],"answer":2,"why":"on the house تعني مجاناً على حساب المطعم."}],"post":["Have you ever had a problem with food at a restaurant? What did you do?","What is your pet peeve?","Do you take leftovers home? Why or why not?"],"tip":"ابدأ الشكوى بكلمة Actually لتكون ألطف: Actually, my steak is burnt. وهي أفضل من أن تبدأ بـ This is bad!"},{"n":7,"week":27,"title":"Who Pays the Bill?","group":1,"level":"B1","setting":"Khalid and his classmate Daniel finish lunch. Both want to pay.","setting_ar":"خالد وزميله دانيال أنهيا الغداء، وكلٌّ منهما يريد أن يدفع.","speakers":["Daniel","Khalid"],"pre":["في ثقافتنا من يدفع عادةً عندما يأكل الأصدقاء معاً؟","هل جرّبت أن يدفع كلٌّ عن نفسه؟"],"idioms":[{"e":"It's on me","m":"It's on me","ar":"الحساب عليّ","ex":"Put your wallet away. It's on me."},{"e":"my treat","m":"my treat","ar":"أنا أعزمك، على حسابي","ex":"Let's have coffee. My treat!"},{"e":"I insist","m":"I insist","ar":"أُصرّ","ex":"Please take the last piece. I insist."},{"e":"go Dutch","m":"go Dutch","ar":"يدفع كلٌّ عن نفسه","ex":"Students often go Dutch when they eat out."},{"e":"pick up the tab","m":"pick up the tab","ar":"يدفع الفاتورة كلها","ex":"My uncle picked up the tab for the whole family."},{"e":"so-so","m":"so-so","ar":"عادي، ليس جيداً جداً","ex":"\"How was the film?\" \"So-so.\""},{"e":"no great shakes","m":"no great shakes","ar":"ليس شيئاً مميزاً","ex":"The new game is no great shakes."},{"e":"leave a lot to be desired","m":"left a lot to be desired","ar":"فيه نقص كبير، دون المستوى","ex":"The hotel's Wi-Fi left a lot to be desired."}],"keywords":[],"lines":[["Daniel","That was nice. Let me get the check. It's on me."],["Khalid","No way. You paid last time. It's my treat today."],["Daniel","Come on, I insist. You're a guest in my city."],["Khalid","Then let's go Dutch. You pay for yours, and I pay for mine."],["Daniel","OK, fine. But next time I'll pick up the tab."],["Khalid","Deal. So, what did you think of the food?"],["Daniel","Honestly? It was so-so. The pasta was no great shakes."],["Khalid","I agree. And the service left a lot to be desired. We waited twenty minutes for water."],["Daniel","Next time, let's try the Lebanese place on Main Street. People say it's amazing."],["Khalid","Great idea. I miss Arabic food. But remember, that time it's my treat."],["Daniel","We'll see about that!"]],"quiz":[{"q":"Why does Daniel want to pay?","options":["It's Daniel's birthday","Khalid is a guest in his city","He lost a bet"],"answer":1,"why":"قال دانيال: You're a guest in my city."},{"q":"How do they pay in the end?","options":["Each one pays for himself","Daniel pays for both","Khalid pays for both"],"answer":0,"why":"اتفقا على go Dutch، أي يدفع كلٌّ عن نفسه."},{"q":"What was the problem with the service?","options":["The waiter was rude","They got the wrong food","They waited a long time for water"],"answer":2,"why":"قال خالد: We waited twenty minutes for water."},{"q":"\"no great shakes\" means:","options":["delicious","not very good","very cold"],"answer":1,"why":"no great shakes تعني ليس مميزاً."},{"q":"\"pick up the tab\" means:","options":["pay the bill","carry the plates","read the menu"],"answer":0,"why":"pick up the tab يعني يدفع الفاتورة."}],"post":["When you eat with friends, who usually pays?","Describe a meal that was just so-so.","What is the best restaurant for Arabic food in your area?"],"tip":"الضيافة عندنا مهمة، وفي الإنجليزية تقول لصديقك: It's my treat أو It's on me لتعزمه، فإن أصرّ فقل: I insist."},{"n":8,"week":28,"title":"Lunch to Go","group":1,"level":"B1","setting":"Khalid buys a quick lunch at a sandwich shop before class. Leo takes his order.","setting_ar":"خالد يشتري غداءً سريعاً من محل سندويتشات قبل المحاضرة، وليو يأخذ طلبه.","speakers":["Leo","Khalid"],"pre":["هل تأكل غداءك في المطعم أم تأخذه معك؟","ماذا تقول لتطلب كمية قليلة من صوص أو ملح؟"],"idioms":[{"e":"What can I get for you?","m":"What can I get for you?","ar":"ماذا تطلب؟","ex":"Good morning! What can I get for you?"},{"e":"go light on","m":"go light on","ar":"يُقلّل من","ex":"Please go light on the sugar in my tea."},{"e":"at no extra charge","m":"at no extra charge","ar":"بدون تكلفة إضافية","ex":"They delivered the sofa at no extra charge."},{"e":"a meal deal","m":"meal deal","ar":"وجبة كاملة بسعر مخفّض","ex":"The meal deal comes with a drink."},{"e":"side order","m":"side order","ar":"طلب جانبي","ex":"Can I get a side order of salad?"},{"e":"on second thought","m":"on second thought","ar":"بعد أن فكّرت مرة أخرى (غيّرت رأيي)","ex":"I'll take the red one. On second thought, the blue one."},{"e":"pass on","m":"pass on","ar":"يعتذر عن، لا يريد","ex":"I'll pass on dessert, thanks."},{"e":"For here or to go?","m":"For here or to go?","ar":"هل تأكله هنا أم تأخذه معك؟","ex":"\"For here or to go?\" \"To go, please.\""},{"e":"break (a bill)","m":"break a fifty","ar":"يصرف ورقة نقدية كبيرة","ex":"Can you break a hundred-riyal note?"},{"e":"take you up on that","m":"take you up on that","ar":"أقبل عرضك","ex":"\"Come for dinner!\" \"I'll take you up on that.\""}],"keywords":[],"lines":[["Leo","Hi! What can I get for you?"],["Khalid","A turkey sandwich, please. Can you go light on the mayonnaise?"],["Leo","Sure. You can add cheese at no extra charge today."],["Khalid","Great, yes, please."],["Leo","Would you like the meal deal? You get a drink and a side order of chips for two dollars more."],["Khalid","Sounds good. Actually, on second thought, I'll pass on the chips. Can I get a fruit cup instead?"],["Leo","No problem. For here or to go?"],["Khalid","To go, please. I have class in fifteen minutes."],["Leo","OK. Your total comes to eleven fifty."],["Khalid","Can you break a fifty? It's all I have."],["Leo","No worries. Here's your change, and here's a coupon. Your next coffee is free."],["Khalid","Thanks! I'll take you up on that tomorrow morning."]],"quiz":[{"q":"What did Khalid say about the mayonnaise?","options":["He wants extra","He wants it on the side","He wants only a little"],"answer":2,"why":"go light on تعني قلّل منه."},{"q":"What did he get instead of chips?","options":["A cookie","A fruit cup","A salad"],"answer":1,"why":"قال: Can I get a fruit cup instead?"},{"q":"Why did he order to go?","options":["He has class in fifteen minutes","The shop was full","It was raining"],"answer":0,"why":"قال: I have class in fifteen minutes."},{"q":"\"Can you break a fifty?\" means:","options":["Can you fix something?","Can you lower the price?","Can you give me change for fifty dollars?"],"answer":2,"why":"break a fifty يعني يصرف ورقة الخمسين."},{"q":"\"on second thought\" means:","options":["for the second time","I changed my mind after thinking again","I agree with you"],"answer":1,"why":"on second thought تقال عند تغيير الرأي."}],"post":["What do you usually eat for lunch on school days?","Do you prefer to eat in or take food to go?","Tell me about a time you changed your mind at the last moment."],"tip":"إذا أردت تغيير طلبك فابدأ بـ On second thought... وستبدو طبيعياً جداً مثل أهل اللغة."},{"n":9,"week":29,"title":"Booking a Doctor's Appointment","group":2,"level":"B1","setting":"Khalid feels sick. He calls a clinic. Brian answers the phone.","setting_ar":"خالد يشعر بالمرض فيتصل بعيادة، ويرد عليه موظف الاستقبال براين.","speakers":["Brian","Khalid"],"pre":["ماذا تقول عندما تتصل بعيادة لتحجز موعداً؟","ما المعلومات التي يطلبها منك موظف الاستقبال عادةً؟"],"idioms":[{"e":"What's the nature of your visit?","m":"What's the nature of your visit?","ar":"ما سبب زيارتك؟ (سؤال رسمي)","ex":"\"What's the nature of your visit?\" \"I have a toothache.\""},{"e":"come down with","m":"coming down with","ar":"يبدأ يصاب بمرض","ex":"I think I'm coming down with a cold."},{"e":"hang on","m":"Hang on","ar":"انتظر قليلاً","ex":"Hang on, I'll get my pen."},{"e":"have an opening","m":"have an opening","ar":"لديه موعد شاغر","ex":"The barber has an opening at five."},{"e":"I'm afraid not","m":"I'm afraid not","ar":"للأسف لا (رفض مهذب)","ex":"\"Is the shop open?\" \"I'm afraid not.\""},{"e":"short-staffed","m":"short-staffed","ar":"ينقصه موظفون","ex":"The café is short-staffed, so service is slow."},{"e":"you're in luck","m":"you're in luck","ar":"حظك جيد","ex":"You're in luck. We have one ticket left."}],"keywords":[],"lines":[["Brian","Good morning, Riverside Clinic. How can I help you?"],["Khalid","Hi. I'd like to make an appointment with a doctor, please."],["Brian","Are you a patient here?"],["Khalid","No, I'm a visiting student. I have travel health insurance."],["Brian","That's fine. What's the nature of your visit?"],["Khalid","I think I'm coming down with something. I have a sore throat and a fever."],["Brian","Hang on, let me check the schedule. ... Dr. Patel doesn't have an opening until Thursday."],["Khalid","Thursday? Is there anything sooner?"],["Brian","I'm afraid not. We're short-staffed this week. Two doctors are sick."],["Khalid","Oh no. I really don't feel well."],["Brian","Wait, you're in luck. Someone just cancelled. Can you come at two thirty today?"],["Khalid","Yes, perfect. Thank you so much!"],["Brian","Please bring your passport and insurance card, and come ten minutes early."]],"quiz":[{"q":"What are Khalid's symptoms?","options":["A sore throat and a fever","A headache","Back pain"],"answer":0,"why":"قال: I have a sore throat and a fever."},{"q":"Why are there few appointments this week?","options":["It's a holiday","The clinic is new","Two doctors are sick"],"answer":2,"why":"قال براين: We're short-staffed. Two doctors are sick."},{"q":"When is Khalid's appointment?","options":["On Thursday","At 2:30 today","Tomorrow morning"],"answer":1,"why":"ألغى شخص موعده، فصار موعد خالد الساعة الثانية والنصف اليوم."},{"q":"\"come down with\" means:","options":["start to get an illness","go downstairs","feel better"],"answer":0,"why":"come down with يعني يبدأ يصاب بمرض."},{"q":"\"You're in luck\" means:","options":["you are sick","you are late","something good happened for you"],"answer":2,"why":"you're in luck تعني «حظك جيد»."}],"post":["When was the last time you went to the doctor?","What do you do when you start to come down with a cold?","Is it easy to get a doctor's appointment where you live?"],"tip":"I'm afraid not طريقة مهذبة جداً لقول «لا». استعملها بدلاً من No فقط عندما تعتذر."},{"n":10,"week":30,"title":"At the Doctor's","group":2,"level":"B1","setting":"Khalid sees Dr. Patel about his sore throat and fever.","setting_ar":"خالد عند الدكتور باتيل بسبب التهاب الحلق والحمّى.","speakers":["Dr. Patel","Khalid"],"pre":["كيف تصف للطبيب ما تشعر به بالإنجليزية؟","هل تعرف لماذا لا تفيد المضادات الحيوية في الزكام؟"],"idioms":[{"e":"under the weather","m":"under the weather","ar":"متوعّك قليلاً","ex":"I'm a bit under the weather today."},{"e":"on the high side","m":"on the high side","ar":"مرتفع قليلاً","ex":"The price is on the high side."},{"e":"going around","m":"going around","ar":"منتشر بين الناس (مرض)","ex":"There's a flu going around at school."},{"e":"garden-variety","m":"garden-variety","ar":"عادي، من النوع الشائع","ex":"It's just a garden-variety headache."},{"e":"magic bullet","m":"magic bullet","ar":"حل سحري سريع","ex":"There's no magic bullet for learning English: practise every day."},{"e":"back on your feet","m":"back on your feet","ar":"تتعافى وتعود لنشاطك","ex":"After the flu, it took me a week to get back on my feet."},{"e":"or so","m":"or so","ar":"تقريباً","ex":"The trip takes an hour or so."},{"e":"drag on","m":"drags on","ar":"يطول أكثر من اللازم","ex":"The meeting dragged on for three hours."}],"keywords":[],"lines":[["Dr. Patel","Hello, Khalid. What brings you in today?"],["Khalid","I've been feeling under the weather since Sunday."],["Dr. Patel","Let's take a look. Your temperature is on the high side: thirty-eight point five."],["Khalid","Is it serious?"],["Dr. Patel","I don't think so. There's a virus going around. Many students in town have it."],["Khalid","So it's not the flu?"],["Dr. Patel","No. It's just a garden-variety cold with a sore throat."],["Khalid","Can you give me antibiotics? I want it to go away fast."],["Dr. Patel","Antibiotics don't work on viruses. I'm afraid there's no magic bullet for a cold."],["Khalid","So what should I do?"],["Dr. Patel","Rest, drink lots of water, and take this medicine for the fever. You'll be back on your feet in five days or so."],["Khalid","And if it drags on?"],["Dr. Patel","If you still feel sick after a week, come back and see me."]],"quiz":[{"q":"What is Khalid's temperature?","options":["36.5","38.5","40"],"answer":1,"why":"قال الطبيب: thirty-eight point five."},{"q":"What does Khalid have?","options":["A common cold","The flu","An allergy"],"answer":0,"why":"قال الطبيب: a garden-variety cold."},{"q":"Why won't the doctor give antibiotics?","options":["They are too expensive","Khalid is allergic to them","They don't work on viruses"],"answer":2,"why":"قال: Antibiotics don't work on viruses."},{"q":"\"under the weather\" means:","options":["outside in the rain","a little sick","very happy"],"answer":1,"why":"under the weather تعني متوعّك قليلاً."},{"q":"\"back on your feet\" means:","options":["healthy and active again","standing up","walking home"],"answer":0,"why":"back on your feet تعني تعافيت وعدت لنشاطك."}],"post":["What do you do to get back on your feet when you have a cold?","Is anything going around at your school these days?","Do you think people take medicine too often? Why?"],"tip":"لتصف مرضاً خفيفاً قل: I'm feeling under the weather. وهي ألطف وأدق من I'm sick."},{"n":11,"week":31,"title":"At the Pharmacy","group":2,"level":"B1","setting":"Khalid has an itchy rash on his arm. He asks the pharmacist, Mr. Green, for help.","setting_ar":"ظهرت على ذراع خالد حكّة واحمرار، فيسأل الصيدلي السيد غرين.","speakers":["Mr. Green","Khalid"],"pre":["هل تسأل الصيدلي قبل أن تذهب إلى الطبيب أحياناً؟","ما الذي قد يسبّب الحساسية في الجلد؟"],"idioms":[{"e":"drive someone nuts","m":"driving me nuts","ar":"يزعجه جداً، يجنّنه","ex":"The noise from the street is driving me nuts."},{"e":"any number of things","m":"any number of things","ar":"أشياء كثيرة محتملة","ex":"A headache can come from any number of things."},{"e":"allergic reaction","m":"allergic reaction","ar":"تفاعل تحسّسي","ex":"He had an allergic reaction to peanuts."},{"e":"hit the nail on the head","m":"hit the nail on the head","ar":"أصاب كبد الحقيقة","ex":"You hit the nail on the head. That's exactly the problem."},{"e":"for starters","m":"For starters","ar":"كبداية، أولاً","ex":"For starters, drink more water."},{"e":"clear up","m":"clear it up","ar":"يزول (مرض أو التهاب)","ex":"The cream cleared up my skin in two days."},{"e":"over the counter","m":"over the counter","ar":"يُصرف بدون وصفة طبية","ex":"You can buy this medicine over the counter."},{"e":"nip it in the bud","m":"nip it in the bud","ar":"يوقف المشكلة في بدايتها","ex":"If a student is late often, nip it in the bud."},{"e":"better safe than sorry","m":"Better safe than sorry","ar":"الحذر خير من الندم","ex":"Take an umbrella. Better safe than sorry."}],"keywords":[],"lines":[["Mr. Green","Hi there. Can I help you?"],["Khalid","Yes, please. I have this red rash on my arm, and it's driving me nuts. It itches all the time."],["Mr. Green","Let me see. When did it start?"],["Khalid","Yesterday, after I used a new soap from the hotel."],["Mr. Green","It could be any number of things, but it looks like an allergic reaction."],["Khalid","I think it's the soap."],["Mr. Green","You may have hit the nail on the head. For starters, stop using that soap."],["Khalid","OK. Is there a cream I can use?"],["Mr. Green","Yes. This cream should clear it up in two or three days. Use it twice a day."],["Khalid","Do I need a prescription?"],["Mr. Green","No, you can buy it over the counter. It's best to nip it in the bud before it spreads."],["Khalid","Should I see a doctor too?"],["Mr. Green","If it gets worse or your face swells, see a doctor right away. Better safe than sorry."]],"quiz":[{"q":"What probably caused the rash?","options":["Some food","The sun","A new soap"],"answer":2,"why":"قال خالد إن الحكة بدأت بعد صابون الفندق الجديد."},{"q":"How often should Khalid use the cream?","options":["Once a week","Twice a day","Every hour"],"answer":1,"why":"قال الصيدلي: Use it twice a day."},{"q":"When should Khalid see a doctor?","options":["If it gets worse or his face swells","Tomorrow morning","Never"],"answer":0,"why":"قال: If it gets worse or your face swells."},{"q":"\"driving me nuts\" means:","options":["driving a car","eating nuts","annoying me a lot"],"answer":2,"why":"drive someone nuts يعني يزعجه جداً."},{"q":"\"over the counter\" means:","options":["on the table","without a prescription","very expensive"],"answer":1,"why":"over the counter يعني يُصرف بدون وصفة."}],"post":["Are you allergic to anything?","What medicine do you usually buy over the counter?","Tell me about a time you were glad you said 'better safe than sorry'."],"tip":"المثل Better safe than sorry يقابله عندنا «الوقاية خير من العلاج»، وتقوله لتنصح شخصاً بالحذر."},{"n":12,"week":32,"title":"At the Dentist","group":2,"level":"B1","setting":"One of Khalid's teeth hurts. He visits Dr. Kim, a dentist.","setting_ar":"أحد أضراس خالد يؤلمه، فيزور طبيب الأسنان الدكتور كيم.","speakers":["Dr. Kim","Khalid"],"pre":["متى زرت طبيب الأسنان آخر مرة؟","ما الذي يسبّب تسوّس الأسنان؟"],"idioms":[{"e":"act up","m":"acting up","ar":"يسبّب مشكلات، لا يعمل جيداً","ex":"My laptop is acting up again."},{"e":"give someone trouble","m":"giving you trouble","ar":"يسبّب له متاعب","ex":"My knee has been giving me trouble since the match."},{"e":"get to the bottom of","m":"get to the bottom of","ar":"يعرف السبب الحقيقي","ex":"The teacher wants to get to the bottom of the problem."},{"e":"give it a once-over","m":"give your other teeth a once-over","ar":"يفحصه فحصاً سريعاً","ex":"Can you give my essay a once-over?"},{"e":"off the top of my head","m":"Off the top of my head","ar":"من ذاكرتي دون أن أتحقق","ex":"Off the top of my head, there are thirty students in my class."},{"e":"due for","m":"due for","ar":"حان وقت","ex":"My car is due for an oil change."},{"e":"covered by","m":"covered by","ar":"يغطيه (التأمين)","ex":"Is this test covered by my insurance?"},{"e":"out-of-pocket","m":"out-of-pocket","ar":"تدفعه من جيبك","ex":"Glasses were an out-of-pocket cost for me."},{"e":"in the meantime","m":"In the meantime","ar":"في هذه الأثناء، إلى ذلك الحين","ex":"The bus comes at six. In the meantime, let's have tea."}],"keywords":[],"lines":[["Dr. Kim","So, Khalid, what's the problem?"],["Khalid","One of my back teeth has been acting up. It hurts when I drink cold water."],["Dr. Kim","How long has it been giving you trouble?"],["Khalid","About a week. It's getting worse."],["Dr. Kim","Let's get to the bottom of this. I'll take an X-ray first. ... Hmm, you have a small cavity."],["Khalid","Can you fix it today?"],["Dr. Kim","Yes, it's a small filling. While you're here, I'll also give your other teeth a once-over. When was your last checkup?"],["Khalid","Off the top of my head, I'd say about a year ago."],["Dr. Kim","Then you're due for a cleaning too."],["Khalid","Is the filling covered by my insurance?"],["Dr. Kim","Our office will check. If not, it will be an out-of-pocket cost of about one hundred twenty dollars."],["Khalid","OK. And the cleaning?"],["Dr. Kim","Let's do the filling now and book the cleaning for next week. In the meantime, brush gently and avoid very cold drinks."]],"quiz":[{"q":"When does Khalid's tooth hurt?","options":["When he drinks cold water","When he sleeps","When he walks"],"answer":0,"why":"قال: It hurts when I drink cold water."},{"q":"What does Khalid have?","options":["A broken tooth","Nothing serious at all","A small cavity"],"answer":2,"why":"قال الطبيب: you have a small cavity."},{"q":"How much will the filling cost if insurance doesn't cover it?","options":["About $20","About $120","About $1,200"],"answer":1,"why":"قال: about one hundred twenty dollars."},{"q":"\"acting up\" means:","options":["causing problems","acting in a play","getting better"],"answer":0,"why":"act up يعني يسبّب مشكلات."},{"q":"\"Off the top of my head\" means:","options":["on my hair","with a headache","quickly from memory, without checking"],"answer":2,"why":"off the top of my head تعني من ذاكرتي دون تحقق."}],"post":["How often do you visit the dentist?","What do you do to keep your teeth healthy?","What sweet food is hard for you to give up?"],"tip":"عبارة Off the top of my head مفيدة عندما يسألك أحد عن رقم أو تاريخ ولست متأكداً تماماً."},{"n":13,"week":33,"title":"Arriving at a Dinner","group":3,"level":"B1","setting":"Khalid is invited to dinner at the home of his host family, the Millers. He arrives late.","setting_ar":"خالد مدعوّ إلى العشاء في بيت عائلة ميلر المضيفة، لكنه وصل متأخراً.","speakers":["Mr. Miller","Khalid"],"pre":["ماذا تحمل معك عادةً عندما تزور أحداً في بيته؟","ماذا تقول إذا وصلت متأخراً إلى موعد؟"],"idioms":[{"e":"get held up","m":"got held up","ar":"تأخّر بسبب شيء","ex":"Sorry I'm late. I got held up at work."},{"e":"pile-up","m":"pile-up","ar":"حادث تصادم عدة سيارات","ex":"There was a pile-up on the highway in the fog."},{"e":"sit in traffic","m":"sat in traffic","ar":"علق في زحمة السير","ex":"We sat in traffic for an hour."},{"e":"What a nightmare!","m":"What a nightmare!","ar":"يا له من موقف مزعج!","ex":"Your flight was cancelled twice? What a nightmare!"},{"e":"a little something","m":"a little something","ar":"هدية بسيطة","ex":"I brought you a little something from Abha."},{"e":"You shouldn't have!","m":"You shouldn't have!","ar":"ما كان له داعٍ! (شكر على هدية)","ex":"Flowers for me? You shouldn't have!"},{"e":"Join the party!","m":"Join the party!","ar":"انضم إلينا!","ex":"We're all in the garden. Join the party!"},{"e":"hold the ice","m":"hold the ice","ar":"بدون ثلج","ex":"A lemon juice, please, and hold the ice."},{"e":"Coming right up","m":"Coming right up","ar":"حالاً، سيأتي فوراً","ex":"\"Two teas, please.\" \"Coming right up!\""},{"e":"chill out","m":"chill out","ar":"يسترخي ويهدأ","ex":"It's the weekend. Just chill out."}],"keywords":[],"lines":[["Mr. Miller","Khalid! Come in, come in. We were starting to worry."],["Khalid","I'm so sorry I'm late. My bus got held up on the highway."],["Mr. Miller","Oh no, what happened?"],["Khalid","There was a pile-up near the bridge. We sat in traffic for forty minutes."],["Mr. Miller","What a nightmare! Was anyone hurt?"],["Khalid","I don't think so. Here, I brought you a little something. These are dates from Al-Baha."],["Mr. Miller","Oh, Khalid, you shouldn't have! They look delicious."],["Khalid","In Saudi Arabia we always serve dates with coffee."],["Mr. Miller","Then we'll have them with coffee after dinner. Everyone's in the living room. Join the party!"],["Khalid","Thank you. It smells wonderful in here."],["Mr. Miller","Can I get you something to drink?"],["Khalid","Some lemonade, please, but hold the ice. My throat is still a little sore."],["Mr. Miller","Coming right up. Now sit down and chill out. You've had a long trip."]],"quiz":[{"q":"Why was Khalid late?","options":["He got lost","There was a crash on the highway","He forgot the time"],"answer":1,"why":"قال إن حافلته علقت بسبب pile-up، أي حادث تصادم."},{"q":"What did Khalid bring?","options":["Dates","Flowers","A cake"],"answer":0,"why":"قال: These are dates from Al-Baha."},{"q":"Why didn't Khalid want ice?","options":["He doesn't like cold drinks","There was no ice","His throat is still a little sore"],"answer":2,"why":"قال: My throat is still a little sore."},{"q":"\"You shouldn't have!\" means:","options":["you made a mistake","a polite thank-you for a gift","please don't come"],"answer":1,"why":"You shouldn't have! شكر لطيف على هدية."},{"q":"\"I got held up\" here means:","options":["I was delayed","Someone robbed me","Someone carried me"],"answer":0,"why":"held up هنا تعني تأخّر."}],"post":["What gift do you take when you visit someone's home?","Tell me about a time you got held up on the way somewhere.","How do people in your family welcome guests?"],"tip":"عندما يقدّم لك أحد هدية فقل: You shouldn't have! ثم Thank you so much. فهي شكر وتواضع معاً."},{"n":14,"week":34,"title":"Meeting New People","group":3,"level":"B1","setting":"At the Millers' dinner, Khalid meets Jake. Jake thinks they have met before.","setting_ar":"في عشاء عائلة ميلر يقابل خالد جيك، ويظن جيك أنهما التقيا من قبل.","speakers":["Jake","Khalid"],"pre":["ماذا تقول إذا نسيت اسم شخص قابلته من قبل؟","كيف تبدأ حديثاً مع شخص لا تعرفه؟"],"idioms":[{"e":"look familiar","m":"look familiar","ar":"يبدو مألوفاً لي","ex":"That man looks familiar. Is he your teacher?"},{"e":"I can't quite place you","m":"I can't quite place you","ar":"لا أتذكر أين رأيتك","ex":"I know your face, but I can't quite place you."},{"e":"cross paths","m":"our paths crossed","ar":"التقيا مصادفة","ex":"Our paths crossed at a conference in Riyadh."},{"e":"ring a bell","m":"rings a bell","ar":"يذكّرني بشيء، مألوف","ex":"His name rings a bell."},{"e":"It's a small world!","m":"It's a small world!","ar":"ما أصغر الدنيا!","ex":"You know my cousin too? It's a small world!"},{"e":"I didn't catch your name","m":"I didn't catch your name","ar":"لم أسمع اسمك جيداً","ex":"Sorry, I didn't catch your name."},{"e":"fill someone in","m":"filled me in","ar":"يُطلعه على التفاصيل","ex":"Can you fill me in on the meeting?"},{"e":"have a lot in common","m":"have a lot in common","ar":"بيننا أشياء مشتركة كثيرة","ex":"My brother and I have a lot in common."},{"e":"What have you been up to?","m":"what have you been up to","ar":"ماذا كنت تفعل مؤخراً؟","ex":"Long time no see! What have you been up to?"},{"e":"make introductions","m":"make some introductions","ar":"يعرّف الناس ببعضهم","ex":"Let me make some introductions."}],"keywords":[],"lines":[["Jake","Hi. You look familiar. Have we met before?"],["Khalid","Maybe. I'm sorry, I can't quite place you."],["Jake","I think our paths crossed at the city library last week. You asked me where the study rooms were."],["Khalid","Oh, yes! That rings a bell. You were at the front desk."],["Jake","That's right. It's a small world! I'm the Millers' nephew."],["Khalid","Nice to see you again. I'm sorry, I didn't catch your name at the library."],["Jake","It's Jake. And you're Khalid, right? My uncle filled me in about you. You're from Saudi Arabia."],["Khalid","Yes, from Al-Baha. It's in the mountains in the south."],["Jake","Mountains? I love hiking! I want to visit Saudi Arabia one day."],["Khalid","Really? I go hiking almost every weekend at home. I think we have a lot in common."],["Jake","So, what have you been up to since the library?"],["Khalid","Studying, mostly. My course is hard but fun."],["Jake","Come on, let me make some introductions. You should meet my brother. He loves mountains too."]],"quiz":[{"q":"Where did Khalid and Jake first meet?","options":["At the airport","At school","At the city library"],"answer":2,"why":"قال جيك: our paths crossed at the city library."},{"q":"Who is Jake?","options":["Khalid's teacher","The Millers' nephew","Khalid's neighbour"],"answer":1,"why":"قال: I'm the Millers' nephew."},{"q":"What do they both enjoy?","options":["Hiking","Football","Cooking"],"answer":0,"why":"كلاهما يحب المشي في الجبال (hiking)."},{"q":"\"That rings a bell\" means:","options":["The phone is ringing","It's time for class","That sounds familiar"],"answer":2,"why":"rings a bell تعني يذكّرني بشيء."},{"q":"\"I didn't catch your name\" means:","options":["I couldn't run fast enough","I didn't hear or remember your name","I lost your card"],"answer":1,"why":"didn't catch your name تعني لم أسمع اسمك جيداً."}],"post":["Have you ever met someone you knew in a surprising place?","What do you say when you forget someone's name?","What do you have in common with your best friend?"],"tip":"إذا نسيت اسم شخص فلا تُحرج نفسك، بل قل: I'm sorry, I didn't catch your name. فهي تعني أن الخطأ في السماع لا في الذاكرة."},{"n":15,"week":35,"title":"Thanking Your Host","group":3,"level":"B1","setting":"Khalid enjoys dinner with the Millers and thanks his host before he leaves.","setting_ar":"خالد يستمتع بالعشاء مع عائلة ميلر ويشكر مضيفه قبل أن يغادر.","speakers":["Mr. Miller","Khalid"],"pre":["كيف تمدح طعاماً أعجبك بالإنجليزية؟","ماذا تقول لمضيفك عندما تغادر بيته؟"],"idioms":[{"e":"help yourself","m":"help yourself","ar":"تفضّل وخذ بنفسك","ex":"There's tea in the kitchen. Help yourself."},{"e":"out of this world","m":"out of this world","ar":"رائع جداً، لا مثيل له","ex":"My grandmother's kabsa is out of this world."},{"e":"melt in your mouth","m":"melts in your mouth","ar":"طريّ جداً يذوب في الفم","ex":"This cake melts in your mouth."},{"e":"seconds","m":"seconds","ar":"صحن ثانٍ، زيادة من الطعام","ex":"The soup was so good that I had seconds."},{"e":"save room for","m":"save room for","ar":"اترك مكاناً في معدتك لـ","ex":"Don't eat too much. Save room for dessert."},{"e":"a real treat","m":"a real treat","ar":"متعة حقيقية","ex":"Visiting the old village was a real treat."},{"e":"Thank you for a lovely time","m":"Thank you for a lovely time","ar":"شكراً على الوقت الجميل","ex":"Thank you for a lovely time. See you soon."},{"e":"hold someone to that","m":"hold you to that","ar":"سأذكّرك بوعدك","ex":"You'll help me move? I'll hold you to that!"}],"keywords":[],"lines":[["Mr. Miller","Please, help yourself. There's plenty of food."],["Khalid","Thank you. This chicken is out of this world! How did you make it?"],["Mr. Miller","It's my mother's recipe. The secret is lemon and garlic."],["Khalid","The rice is great too. It melts in your mouth."],["Mr. Miller","Would you like seconds?"],["Khalid","Yes, please, just a little. I didn't expect food here to taste like home."],["Mr. Miller","That makes me so happy. But save room for dessert. We made a carrot cake."],["Khalid","I always have room for cake!"],["Mr. Miller","... I'm glad you could come tonight, Khalid."],["Khalid","Thank you for a lovely time. The dinner was a real treat."],["Mr. Miller","It was our pleasure. You're welcome here any time."],["Khalid","Next time, I'll cook for you. I make a great kabsa."],["Mr. Miller","It's a deal. We'll hold you to that!"]],"quiz":[{"q":"What is the secret of the chicken?","options":["Lemon and garlic","Honey","Saudi spices"],"answer":0,"why":"قال: The secret is lemon and garlic."},{"q":"What is for dessert?","options":["Apple pie","Ice cream","Carrot cake"],"answer":2,"why":"قال: We made a carrot cake."},{"q":"What will Khalid cook next time?","options":["Chicken","Kabsa","Cake"],"answer":1,"why":"قال: I make a great kabsa."},{"q":"\"out of this world\" means:","options":["extremely good","from space","strange"],"answer":0,"why":"out of this world تعني رائع جداً."},{"q":"\"Would you like seconds?\" means:","options":["Can you wait a moment?","Did you come second?","Would you like more food?"],"answer":2,"why":"seconds هنا تعني صحناً ثانياً من الطعام."}],"post":["What dish from your home is out of this world?","How do you thank someone after a visit?","Can you cook anything? Tell me how you make it."],"tip":"عند المغادرة قل: Thank you for a lovely time. وإذا أعجبك الطعام قل: It was out of this world!"},{"n":16,"week":36,"title":"A Flight Delay","group":4,"level":"B1","setting":"Khalid is flying to Chicago, but his flight is delayed. He talks to Marco, another passenger.","setting_ar":"خالد مسافر إلى شيكاغو لكن رحلته تأخرت، فيتحدث مع مسافر آخر اسمه ماركو.","speakers":["Marco","Khalid"],"pre":["ماذا تفعل إذا تأخرت رحلتك ساعات؟","هل الغضب من موظف المطار يحل المشكلة؟"],"idioms":[{"e":"for crying out loud","m":"For crying out loud","ar":"يا للعجب! (تعبير عن الضيق)","ex":"For crying out loud, the lift is broken again!"},{"e":"don't hold your breath","m":"don't hold your breath","ar":"لا تتوقع حدوثه قريباً","ex":"He says he'll call. Don't hold your breath."},{"e":"in the same boat","m":"in the same boat","ar":"في الموقف الصعب نفسه","ex":"We all have exams tomorrow. We're in the same boat."},{"e":"give someone a piece of one's mind","m":"give that agent a piece of my mind","ar":"يوبّخه ويعبّر عن غضبه","ex":"I wanted to give him a piece of my mind."},{"e":"No way!","m":"No way!","ar":"مستحيل! غير معقول!","ex":"The match was cancelled? No way!"},{"e":"waiting list","m":"waiting list","ar":"قائمة الانتظار","ex":"I'm on the waiting list for the course."},{"e":"quite a few","m":"Quite a few","ar":"عدد كبير نوعاً ما","ex":"Quite a few students came early."},{"e":"keep each other posted","m":"keep each other posted","ar":"نتبادل الأخبار أولاً بأول","ex":"Keep me posted about your exam results."}],"keywords":[],"lines":[["Marco","Did you hear that? Our flight to Chicago is delayed again!"],["Khalid","For crying out loud! That's the third time today."],["Marco","They say it will leave at six. But don't hold your breath."],["Khalid","I have a meeting with my professor tomorrow morning. Are you going for work?"],["Marco","Yes, so we're in the same boat. I'm going to give that agent a piece of my mind."],["Khalid","It's not his fault, though. It's the storm."],["Marco","You're right. I'll go and ask politely about other flights. ..."],["Marco","OK, I talked to the agent. The six o'clock flight is cancelled."],["Khalid","No way! What can we do?"],["Marco","There's a flight at nine, but it's full. He can put us on the waiting list."],["Khalid","How many people are on the list already?"],["Marco","Quite a few, I'm afraid. About twenty."],["Khalid","Then I'll ask about a train too. Let's keep each other posted."],["Marco","Good idea. Here's my number."]],"quiz":[{"q":"Why is the flight delayed?","options":["Because the plane is broken","Because of a storm","Because there is no pilot"],"answer":1,"why":"قال خالد: It's the storm."},{"q":"What happened to the six o'clock flight?","options":["It was cancelled","It left early","It changed gates"],"answer":0,"why":"قال ماركو: The six o'clock flight is cancelled."},{"q":"How many people are on the waiting list?","options":["Two","Nobody","About twenty"],"answer":2,"why":"قال: Quite a few. About twenty."},{"q":"\"in the same boat\" means:","options":["travelling by sea","in the same difficult situation","sitting together"],"answer":1,"why":"in the same boat تعني في الموقف نفسه."},{"q":"\"Let's keep each other posted\" means:","options":["Let's give each other the latest news","Let's send letters","Let's stay together"],"answer":0,"why":"keep someone posted يعني يُطلعه على الأخبار."}],"post":["Have you ever had a delayed or cancelled flight? What happened?","Is it a good idea to give staff a piece of your mind? Why?","What do you do to pass the time at an airport?"],"tip":"لاحظ أن خالد ذكّر ماركو بأن الموظف غير مذنب، فغيّر ماركو أسلوبه وسأل politely. الأدب يحل المشكلات أسرع من الغضب."},{"n":17,"week":37,"title":"Lost Luggage","group":4,"level":"B1","setting":"Khalid lands in Chicago, but his suitcase doesn't arrive. He goes to the baggage desk.","setting_ar":"وصل خالد إلى شيكاغو لكن حقيبته لم تصل، فذهب إلى مكتب الأمتعة.","speakers":["Mr. Lee","Khalid"],"pre":["ماذا تضع في حقيبة اليد تحسّباً لضياع حقيبتك الكبيرة؟","كيف تصف حقيبتك بالإنجليزية؟"],"idioms":[{"e":"show up","m":"show up","ar":"يظهر، يصل","ex":"My friend didn't show up at the meeting."},{"e":"bear with me","m":"Bear with me","ar":"اصبر عليّ قليلاً","ex":"Bear with me. The computer is slow."},{"e":"track down","m":"track it down","ar":"يبحث حتى يجد","ex":"The police tracked down the stolen car."},{"e":"at the latest","m":"at the latest","ar":"على أقصى تقدير","ex":"Send me the file by Monday at the latest."},{"e":"pay someone back","m":"pay you back","ar":"يعيد إليه ما دفعه","ex":"I'll pay you back tomorrow."},{"e":"file a claim","m":"file a claim","ar":"يقدّم طلب تعويض","ex":"You can file a claim on the airline's website."},{"e":"fingers crossed","m":"Fingers crossed","ar":"أتمنى ذلك، على أمل","ex":"Fingers crossed I pass the test!"},{"e":"turn up","m":"turns up","ar":"يُعثر عليه، يظهر بعد ضياع","ex":"My lost keys turned up in my bag."}],"keywords":[],"lines":[["Mr. Lee","Next, please. How can I help you?"],["Khalid","My suitcase didn't show up on the belt. I waited until everyone left."],["Mr. Lee","I'm sorry. Do you have your baggage tag?"],["Khalid","Yes, here it is. It's a big black suitcase with a green ribbon on the handle."],["Mr. Lee","Bear with me while I check the system. ... It looks like your bag never left Boston."],["Khalid","Oh no. All my clothes are in it."],["Mr. Lee","Don't worry. We'll track it down. It will probably be on the next flight."],["Khalid","When can I get it?"],["Mr. Lee","Tomorrow by noon at the latest. We'll deliver it to your hotel."],["Khalid","And what about tonight? I don't even have a toothbrush."],["Mr. Lee","Keep your receipts. The airline will pay you back for basic things. You can file a claim online."],["Khalid","OK. Fingers crossed it turns up tomorrow."],["Mr. Lee","I'm sure it will. Here's your reference number."]],"quiz":[{"q":"Where is Khalid's suitcase?","options":["In Chicago","Nobody knows","Still in Boston"],"answer":2,"why":"قال الموظف: your bag never left Boston."},{"q":"How can people recognise his suitcase?","options":["It has a red cover","It has a green ribbon on the handle","His name is on it in big letters"],"answer":1,"why":"قال: with a green ribbon on the handle."},{"q":"What should Khalid keep?","options":["His receipts","His boarding pass only","The bag tag only"],"answer":0,"why":"قال الموظف: Keep your receipts."},{"q":"\"Bear with me\" means:","options":["Carry this for me","Be strong","Please wait patiently"],"answer":2,"why":"Bear with me تعني اصبر عليّ قليلاً."},{"q":"\"at the latest\" means:","options":["the newest","not later than","maybe"],"answer":1,"why":"at the latest تعني على أقصى تقدير."}],"post":["What do you always keep in your carry-on bag?","Describe your suitcase in English.","Have you ever lost something important? Did it turn up?"],"tip":"عندما تتأخر في البحث أو العمل وأمامك شخص ينتظر، قل: Bear with me, please. وهي مهذبة جداً."},{"n":18,"week":38,"title":"Renting a Car","group":4,"level":"B1","setting":"Khalid's cousin Saad rents a car for a three-day trip. Rob works at the rental desk.","setting_ar":"سعد ابن عم خالد يستأجر سيارة لرحلة مدتها ثلاثة أيام، وروب موظف التأجير.","speakers":["Rob","Saad"],"pre":["ماذا تسأل عنه قبل أن تستأجر سيارة؟","لماذا يجب أن تقرأ العقد قبل التوقيع؟"],"idioms":[{"e":"have in mind","m":"in mind","ar":"يفكر في شيء محدد","ex":"Do you have a date in mind for the trip?"},{"e":"good on gas","m":"good on gas","ar":"قليل استهلاك الوقود","ex":"Small cars are usually good on gas."},{"e":"run a special","m":"running a special","ar":"يقدّم عرضاً خاصاً","ex":"The shop is running a special on shoes."},{"e":"inclusive of","m":"inclusive of","ar":"شاملاً","ex":"The price is inclusive of breakfast."},{"e":"highway robbery","m":"highway robbery","ar":"سعر مبالغ فيه جداً، سرقة","ex":"Ten riyals for water? That's highway robbery!"},{"e":"read over","m":"read it over","ar":"يقرأه بعناية من أوله لآخره","ex":"Read over your answers before you finish."},{"e":"can't make heads or tails of","m":"can't make heads or tails of","ar":"لا أفهم منه شيئاً","ex":"I can't make heads or tails of these instructions."},{"e":"grace period","m":"grace period","ar":"مهلة إضافية قبل الغرامة","ex":"The library gives a three-day grace period."},{"e":"just in case","m":"just in case","ar":"احتياطاً","ex":"Take a jacket just in case."}],"keywords":[],"lines":[["Rob","Good afternoon. Do you have a reservation?"],["Saad","No. We need a car for three days. Something small and cheap."],["Rob","Do you have a particular model in mind?"],["Saad","Not really. Just something that's good on gas."],["Rob","You're lucky. We're running a special on small cars this week: forty dollars a day."],["Saad","Is that inclusive of insurance?"],["Rob","No, insurance is twenty-five dollars a day extra."],["Saad","Twenty-five a day? That's highway robbery!"],["Rob","I know it seems high, but accidents are expensive. Here's the contract. Please read it over."],["Saad","Honestly, I can't make heads or tails of this part about fuel."],["Rob","It means you return the car with a full tank. If not, we charge you for the gas."],["Saad","OK. What time do I have to bring it back?"],["Rob","By noon on Friday. There's a one-hour grace period, so you won't pay extra before one o'clock."],["Saad","Great. And I'll take the insurance, just in case."]],"quiz":[{"q":"How many days does Saad need the car?","options":["Three","One","Seven"],"answer":0,"why":"قال سعد: We need a car for three days."},{"q":"How much is the car per day, without insurance?","options":["$25","$65","$40"],"answer":2,"why":"العرض: forty dollars a day."},{"q":"How should Saad return the car?","options":["Washed and clean","With a full tank","At the airport"],"answer":1,"why":"قال روب: you return the car with a full tank."},{"q":"\"highway robbery\" means:","options":["a price that is much too high","a crime on the road","a very fast car"],"answer":0,"why":"highway robbery تعني سعراً مبالغاً فيه."},{"q":"\"grace period\" means:","options":["a quiet time","a holiday","extra time before you pay a fee"],"answer":2,"why":"grace period تعني مهلة إضافية قبل الغرامة."}],"post":["What kind of car would you like to rent for a trip? Why?","What was the last thing you thought was highway robbery?","Do you read contracts and instructions carefully?"],"tip":"إذا لم تفهم جزءاً من عقد أو تعليمات فقل بصراحة: I can't make heads or tails of this part. ثم اطلب الشرح."},{"n":19,"week":39,"title":"Checking into a Hotel","group":4,"level":"B1","setting":"Khalid arrives at his hotel late at night. Adam works at the front desk.","setting_ar":"خالد يصل إلى الفندق في وقت متأخر من الليل، وآدم موظف الاستقبال.","speakers":["Adam","Khalid"],"pre":["ما الذي تسأل عنه عندما تصل إلى فندق؟","هل تحب الفنادق القريبة من محطات القطار؟ لماذا؟"],"idioms":[{"e":"check in","m":"checking in","ar":"يسجّل الوصول","ex":"We can check in after two o'clock."},{"e":"booked solid","m":"booked solid","ar":"محجوز بالكامل","ex":"All the hotels in Abha are booked solid in summer."},{"e":"upgrade","m":"upgrade","ar":"يرقّي إلى درجة أعلى","ex":"They upgraded me to business class."},{"e":"at no extra charge","m":"at no extra charge","ar":"بدون تكلفة إضافية","ex":"Parking is at no extra charge."},{"e":"complimentary","m":"complimentary","ar":"مجاني (تقدّمه المنشأة)","ex":"The hotel offers complimentary water."},{"e":"around the clock","m":"around the clock","ar":"على مدار الساعة","ex":"The pharmacy is open around the clock."},{"e":"a stone's throw","m":"a stone's throw","ar":"قريب جداً","ex":"My school is a stone's throw from my house."},{"e":"wake-up call","m":"wake-up call","ar":"مكالمة إيقاظ","ex":"I asked for a wake-up call at five for Fajr."},{"e":"call it a night","m":"call it a night","ar":"ينهي يومه ويذهب لينام","ex":"It's late. Let's call it a night."}],"keywords":[],"lines":[["Adam","Good evening, and welcome to the Lakeview Hotel. Are you checking in?"],["Khalid","Yes. I have a reservation under the name Khalid Al-Ghamdi."],["Adam","Let me see. ... Yes, a single room for two nights. Hmm, I'm afraid there's a problem. Your room isn't ready."],["Khalid","But it's ten at night! I'm really tired."],["Adam","I'm very sorry. We're booked solid this weekend because of a big conference. But I can upgrade you to a suite at no extra charge."],["Khalid","A suite? That's very kind of you."],["Adam","Breakfast is complimentary. It's served from six to ten."],["Khalid","Great. Is there a gym?"],["Adam","Yes, on the second floor. It's open around the clock."],["Khalid","And is the train station far?"],["Adam","Not at all. It's a stone's throw from here, about two minutes on foot."],["Khalid","Perfect. Could I get a wake-up call at seven?"],["Adam","Of course. Here's your key card. Room seven fourteen. Enjoy your stay."],["Khalid","Thank you. I think I'll call it a night."]],"quiz":[{"q":"Why wasn't Khalid's room ready?","options":["He gave the wrong name","The hotel was full because of a conference","He had no reservation"],"answer":1,"why":"قال آدم: We're booked solid because of a big conference."},{"q":"What did Khalid get?","options":["A suite at no extra charge","A discount","A free dinner"],"answer":0,"why":"قال: I can upgrade you to a suite at no extra charge."},{"q":"How far is the train station?","options":["Twenty minutes by bus","You need a taxi","About two minutes on foot"],"answer":2,"why":"قال: about two minutes on foot."},{"q":"Here, \"complimentary\" means:","options":["polite","free","expensive"],"answer":1,"why":"complimentary هنا تعني مجاناً."},{"q":"\"call it a night\" means:","options":["stop and go to sleep","phone someone at night","stay up late"],"answer":0,"why":"call it a night تعني ينهي يومه وينام."}],"post":["What do you look for when you choose a hotel?","What is a stone's throw from your house?","Do you like to stay up late or call it a night early?"],"tip":"في الفندق تسمع complimentary كثيراً، ومعناها مجاني، مثل complimentary breakfast. أما compliment فمعناها مديح، فلا تخلط بينهما."},{"n":20,"week":40,"title":"A Road Trip","group":4,"level":"B1","setting":"Saad is driving on the highway. Khalid keeps giving him advice from the passenger seat.","setting_ar":"سعد يقود على الطريق السريع، وخالد لا يتوقف عن إعطائه النصائح من المقعد المجاور.","speakers":["Saad","Khalid"],"pre":["هل يزعجك من يعطي السائق تعليمات طوال الطريق؟","متى يجب على السائق أن يتوقف للراحة؟"],"idioms":[{"e":"backseat driver","m":"backseat driver","ar":"راكب يعطي السائق تعليمات باستمرار","ex":"My little brother is such a backseat driver."},{"e":"Got it","m":"Got it","ar":"فهمت","ex":"\"Turn right at the mosque.\" \"Got it.\""},{"e":"bite one's tongue","m":"bite my tongue","ar":"يسكت ويمسك لسانه","ex":"I wanted to answer, but I bit my tongue."},{"e":"keep an eye on","m":"keep an eye on","ar":"يراقب","ex":"Can you keep an eye on my bag?"},{"e":"run low on","m":"running low","ar":"يوشك أن ينفد","ex":"We're running low on milk."},{"e":"make a pit stop","m":"make a pit stop","ar":"يتوقف توقفاً قصيراً في الطريق","ex":"Let's make a pit stop at the next town."},{"e":"grab a bite","m":"grab a bite","ar":"يأكل وجبة سريعة","ex":"Let's grab a bite before the match."},{"e":"doze off","m":"dozed off","ar":"يغفو قليلاً","ex":"I dozed off during the long film."}],"keywords":[],"lines":[["Khalid","Saad, slow down! The speed limit is fifty-five."],["Saad","I'm doing fifty-five, Khalid. Stop being a backseat driver."],["Khalid","Sorry. Take the next exit. ... No, wait, the second exit."],["Saad","OK, OK. Got it."],["Khalid","I'll bite my tongue for the rest of the trip. I promise."],["Saad","Thank you. Can you keep an eye on the gas? I think we're running low."],["Khalid","The light just came on. We should make a pit stop soon."],["Saad","There's a gas station in five miles. We can grab a bite there too. I'm starving."],["Khalid","Good idea. After that, I can drive for a while if you're tired."],["Saad","Yes, please. I almost dozed off ten minutes ago."],["Khalid","Then it's definitely time for a break. Safety first."]],"quiz":[{"q":"What is the speed limit?","options":["50","65","55"],"answer":2,"why":"قال خالد: The speed limit is fifty-five."},{"q":"Why do they need to stop?","options":["They have a flat tyre","They are low on gas","They are lost"],"answer":1,"why":"قال سعد: I think we're running low."},{"q":"What will Khalid do after the stop?","options":["Drive for a while","Sleep in the back","Call home"],"answer":0,"why":"قال: I can drive for a while if you're tired."},{"q":"A \"backseat driver\" is:","options":["a driver who sits in the back","a taxi driver","a passenger who keeps telling the driver what to do"],"answer":2,"why":"backseat driver راكب يعطي السائق تعليمات باستمرار."},{"q":"\"doze off\" means:","options":["get angry","fall asleep for a short time","drive fast"],"answer":1,"why":"doze off يعني يغفو قليلاً."}],"post":["Are you a backseat driver? Who is one in your family?","Where do you like to make a pit stop on long trips?","What is the longest car trip you have taken?"],"tip":"قيادة السيارة وأنت متعب خطيرة جداً. إذا شعرت أنك ستغفو فقل: Let's make a pit stop. وتوقف فوراً."},{"n":21,"week":41,"title":"Taking a Taxi","group":4,"level":"B1","setting":"Khalid needs to catch a train. He takes a taxi. Joe is the driver.","setting_ar":"خالد يحتاج أن يلحق بالقطار فيركب سيارة أجرة، وجو هو السائق.","speakers":["Joe","Khalid"],"pre":["ماذا تقول لسائق الأجرة عندما تركب؟","هل تترك للسائق بقية المبلغ (بقشيش)؟"],"idioms":[{"e":"Hop in!","m":"Hop in!","ar":"اركب!","ex":"Hop in! I'll drive you home."},{"e":"Where are you headed?","m":"Where are you headed?","ar":"إلى أين أنت ذاهب؟","ex":"\"Where are you headed?\" \"To the mall.\""},{"e":"bumper-to-bumper","m":"bumper-to-bumper","ar":"زحمة شديدة والسيارات متلاصقة","ex":"Traffic was bumper-to-bumper after the match."},{"e":"make it","m":"make it","ar":"يصل في الوقت المناسب","ex":"Hurry, or we won't make it."},{"e":"back roads","m":"back roads","ar":"طرق جانبية صغيرة","ex":"We took the back roads to avoid traffic."},{"e":"close call","m":"close call","ar":"نجاة بأعجوبة","ex":"The ball almost hit the window. That was a close call!"},{"e":"fender bender","m":"fender bender","ar":"حادث بسيط بين سيارتين","ex":"It was only a fender bender. Nobody was hurt."},{"e":"keep the change","m":"Keep the change","ar":"احتفظ بالباقي","ex":"Here's twenty riyals. Keep the change."}],"keywords":[],"lines":[["Joe","Hop in! Where are you headed?"],["Khalid","To the central train station, please. My train leaves at four fifteen."],["Joe","Hmm, it's three fifty. Traffic downtown is bumper-to-bumper right now."],["Khalid","Oh no. Do you think we'll make it?"],["Joe","I'll take the back roads. They're usually much faster at this time."],["Khalid","Thanks. ... Whoa! That was a close call!"],["Joe","Sorry about that. That guy didn't stop at the red light. We almost had a fender bender."],["Khalid","I'm glad you have fast reactions."],["Joe","Twenty years of driving in this city! ... Here we are, Central Station. And it's only four oh five."],["Khalid","Amazing! How much is it?"],["Joe","Eighteen fifty."],["Khalid","Here's twenty-two. Keep the change."],["Joe","Thanks a lot. Have a good trip!"]],"quiz":[{"q":"What time does Khalid's train leave?","options":["4:15","3:50","4:05"],"answer":0,"why":"قال: My train leaves at four fifteen."},{"q":"Why does Joe take the back roads?","options":["They are shorter","They are more beautiful","Traffic downtown is very heavy"],"answer":2,"why":"قال جو إن زحمة وسط المدينة شديدة."},{"q":"What almost happened?","options":["A flat tyre","A small accident","They missed the train"],"answer":1,"why":"قال: We almost had a fender bender."},{"q":"\"Keep the change\" means:","options":["The extra money is for you","Don't change anything","Give me some coins"],"answer":0,"why":"Keep the change تعني احتفظ بالباقي."},{"q":"\"bumper-to-bumper\" traffic is:","options":["a car crash","an empty road","very heavy and slow"],"answer":2,"why":"bumper-to-bumper تعني زحمة شديدة."}],"post":["How do you usually get around your city?","Tell me about a close call you had.","Do you use taxi apps? Which one is best?"],"tip":"اختصر لسائق الأجرة: To the train station, please. ولا تحتاج جملة طويلة. وعند الدفع: Keep the change."},{"n":22,"week":42,"title":"Making an Excuse","group":5,"level":"B1","setting":"Khalid forgot to go to a basketball game with Jake. Now he apologizes.","setting_ar":"نسي خالد أن يذهب مع جيك إلى مباراة كرة سلة، والآن يعتذر.","speakers":["Jake","Khalid"],"pre":["كيف تعتذر لصديق إذا نسيت موعداً معه؟","هل العذر وحده يكفي، أم يجب أن تعوّضه؟"],"idioms":[{"e":"it slipped my mind","m":"slipped my mind","ar":"نسيته تماماً","ex":"Sorry, your birthday slipped my mind."},{"e":"What a shame!","m":"What a shame.","ar":"يا للأسف","ex":"You missed the trip? What a shame!"},{"e":"at the eleventh hour","m":"at the eleventh hour","ar":"في اللحظة الأخيرة","ex":"He finished his project at the eleventh hour."},{"e":"Don't sweat it","m":"Don't sweat it","ar":"لا تقلق، لا مشكلة","ex":"\"Sorry I'm late.\" \"Don't sweat it.\""},{"e":"These things happen","m":"These things happen","ar":"هذه أمور تحدث","ex":"You dropped your phone? These things happen."},{"e":"a flake","m":"a flake","ar":"شخص لا يُعتمد عليه في مواعيده","ex":"Don't be a flake. Come on time."},{"e":"make it up to someone","m":"make it up to you","ar":"يعوّضه عن خطأ","ex":"I missed your party, but I'll make it up to you."},{"e":"The more the merrier","m":"The more the merrier","ar":"كلما زاد العدد زادت المتعة","ex":"Bring your friends. The more the merrier!"},{"e":"miss out on","m":"miss out on","ar":"يفوته شيء جميل","ex":"Don't miss out on the summer camp."},{"e":"make it","m":"make it","ar":"يحضر، يستطيع المجيء","ex":"I'm sorry, I can't make it tonight."}],"keywords":[],"lines":[["Jake","Hey, Khalid, where were you yesterday? We waited for you at the basketball game."],["Khalid","Oh no! I'm so sorry, Jake. It completely slipped my mind."],["Jake","What a shame. It was a great game. We won by two points!"],["Khalid","I feel terrible. My professor gave us a big project at the eleventh hour, and I worked all evening."],["Jake","Don't sweat it. These things happen."],["Khalid","Thanks, but I don't want you to think I'm a flake. Let me make it up to you."],["Jake","How?"],["Khalid","I'll buy the tickets for the next game. Is there one on Saturday?"],["Jake","Yes, at seven. My brother and two friends are coming too."],["Khalid","Can I bring my cousin Saad?"],["Jake","Of course. The more the merrier!"],["Khalid","Great. I won't miss out on this one. I promise I'll make it."],["Jake","Ha! I'll send you a reminder anyway."]],"quiz":[{"q":"What did Khalid miss?","options":["A class","A basketball game","A dinner"],"answer":1,"why":"قال جيك: We waited for you at the basketball game."},{"q":"Why did Khalid forget?","options":["He worked on a big project","He was sick","He lost his phone"],"answer":0,"why":"قال إن أستاذه أعطاهم مشروعاً كبيراً في اللحظة الأخيرة."},{"q":"How will Khalid make it up to Jake?","options":["He will cook dinner","He will give him a gift","He will buy tickets for the next game"],"answer":2,"why":"قال: I'll buy the tickets for the next game."},{"q":"\"It slipped my mind\" means:","options":["I fell down","I forgot","I changed my mind"],"answer":1,"why":"slipped my mind تعني نسيته."},{"q":"\"at the eleventh hour\" means:","options":["at the last minute","at eleven o'clock","very early"],"answer":0,"why":"at the eleventh hour تعني في اللحظة الأخيرة."}],"post":["What did you forget recently, and what happened?","How do you make it up to a friend after a mistake?","Do you prefer small groups or 'the more the merrier'?"],"tip":"الاعتذار الجيد له ثلاث خطوات: اعترف (It slipped my mind)، ثم اشرح باختصار، ثم عوّض (Let me make it up to you)."},{"n":23,"week":43,"title":"Running Late","group":5,"level":"B1","setting":"Khalid and his classmate Ryan have a presentation. Khalid is late, so Ryan calls him.","setting_ar":"خالد وزميله رايان لديهما عرض تقديمي، وخالد متأخر فاتصل به رايان.","speakers":["Ryan","Khalid"],"pre":["ماذا تفعل إذا عرفت أنك ستتأخر عن موعد مهم؟","كيف تتجنّب التأخر في الصباح؟"],"idioms":[{"e":"running late","m":"running late","ar":"متأخر عن موعدي","ex":"Sorry, I'm running late. Start without me."},{"e":"on my way","m":"on your way","ar":"في الطريق","ex":"Don't worry, I'm on my way."},{"e":"tops","m":"tops","ar":"على الأكثر","ex":"It costs ten riyals, tops."},{"e":"cutting it close","m":"cutting it close","ar":"وقت ضيق جداً","ex":"Leaving at 7:55 for an 8:00 class? That's cutting it close."},{"e":"cover for someone","m":"cover for me","ar":"ينوب عنه أو يغطّي غيابه","ex":"Can you cover for me in class tomorrow?"},{"e":"hold the fort","m":"hold the fort","ar":"يتولى الأمور حتى يعود الآخرون","ex":"Hold the fort while I get the drinks."},{"e":"just in case","m":"just in case","ar":"احتياطاً","ex":"Save your work, just in case."},{"e":"in the nick of time","m":"in the nick of time","ar":"في آخر لحظة، في الوقت المناسب تماماً","ex":"We reached the bus in the nick of time."},{"e":"better late than never","m":"Better late than never","ar":"أن تأتي متأخراً خير من ألا تأتي","ex":"You finally started exercising? Better late than never!"}],"keywords":[],"lines":[["Ryan","Khalid, where are you? Our presentation starts in fifteen minutes!"],["Khalid","I know, I'm so sorry. I'm running late. I missed the bus by one minute."],["Ryan","Are you on your way now?"],["Khalid","Yes, I'm on the next bus. I'll be there in twelve minutes, tops."],["Ryan","That's cutting it close. The professor never waits."],["Khalid","Can you cover for me if I'm a little late? You can start with the introduction."],["Ryan","OK, I'll hold the fort until you arrive. Do you have the slides?"],["Khalid","They're on a USB drive in my bag. I'll email them to you right now, just in case."],["Ryan","Got them. Thanks. ..."],["Khalid","I'm here! Did I miss my part?"],["Ryan","You made it in the nick of time. I just finished the introduction. You're next."],["Khalid","Phew! Better late than never."],["Ryan","Next time, take the earlier bus!"]],"quiz":[{"q":"Why was Khalid late?","options":["He overslept","He forgot the presentation","He missed the bus by one minute"],"answer":2,"why":"قال: I missed the bus by one minute."},{"q":"What will Ryan do?","options":["Tell the professor Khalid is sick","Start with the introduction","Cancel the presentation"],"answer":1,"why":"اقترح خالد أن يبدأ رايان بالمقدمة."},{"q":"How did Khalid send the slides?","options":["By email","On a USB drive","By text message"],"answer":0,"why":"قال: I'll email them to you right now."},{"q":"\"cutting it close\" means:","options":["cutting paper","standing close to someone","leaving very little time"],"answer":2,"why":"cutting it close تعني أن الوقت ضيق جداً."},{"q":"\"in the nick of time\" means:","options":["too late","just in time","for a long time"],"answer":1,"why":"in the nick of time تعني في آخر لحظة."}],"post":["When was the last time you were running late? What happened?","Who covers for you when you are absent?","What do you do the night before an important day?"],"tip":"إذا كنت ستتأخر فاتصل قبل الموعد وقل: I'm running late. I'll be there in ten minutes, tops. فهذا احترام لوقت الآخرين."},{"n":24,"week":44,"title":"A Week of Bad Luck","group":5,"level":"B1","setting":"Khalid has had a terrible week. His cousin Saad tries to cheer him up.","setting_ar":"مرّ خالد بأسبوع سيئ جداً، وابن عمه سعد يحاول أن يرفع معنوياته.","speakers":["Saad","Khalid"],"pre":["ماذا تقول لصديق مرّ بيوم سيئ؟","هل تؤمن أن المصائب تأتي مجتمعة أحياناً؟"],"idioms":[{"e":"down on one's luck","m":"down on my luck","ar":"سيئ الحظ هذه الفترة","ex":"He's down on his luck. He lost his job."},{"e":"When it rains, it pours","m":"When it rains, it pours","ar":"المصائب لا تأتي فرادى","ex":"My car broke and then my phone. When it rains, it pours."},{"e":"It's not my week","m":"It's just not my week","ar":"ليس أسبوعي (كل شيء يسوء)","ex":"I failed the quiz and lost my bag. It's not my day!"},{"e":"hang in there","m":"Hang in there","ar":"اصبر ولا تستسلم","ex":"Exams finish next week. Hang in there!"},{"e":"hand in","m":"hand it in","ar":"يسلّم شيئاً (للمسؤولين)","ex":"Someone found my wallet and handed it in."},{"e":"look on the bright side","m":"Look on the bright side","ar":"انظر إلى الجانب المشرق","ex":"Look on the bright side: you learned something new."},{"e":"It could be worse","m":"It could be worse","ar":"كان يمكن أن يكون أسوأ","ex":"I broke my phone screen, but it could be worse."},{"e":"Things are looking up","m":"Things are looking up","ar":"الأمور بدأت تتحسن","ex":"I found a job. Things are looking up!"}],"keywords":[],"lines":[["Saad","You look upset, Khalid. What's wrong?"],["Khalid","I'm really down on my luck this week. First, I failed my driving test."],["Saad","Oh no. That's too bad."],["Khalid","Then today I lost my wallet on the train, and on the way home my phone fell in a puddle."],["Saad","Wow. When it rains, it pours."],["Khalid","Exactly. It's just not my week."],["Saad","Hang in there. Did you call the train company about your wallet?"],["Khalid","Yes. They said someone might find it and hand it in."],["Saad","Look on the bright side. Your phone still works, right?"],["Khalid","Yes, but the screen is a little dark."],["Saad","See? It could be worse. And you can take the driving test again next month."],["Khalid","You're right. ... Wait, my phone is ringing. It's the train company. Someone found my wallet!"],["Saad","There you go! Things are looking up already."]],"quiz":[{"q":"What test did Khalid fail?","options":["His driving test","A maths exam","A job interview"],"answer":0,"why":"قال: I failed my driving test."},{"q":"Where did he lose his wallet?","options":["At the mall","In a taxi","On the train"],"answer":2,"why":"قال: I lost my wallet on the train."},{"q":"What good news did he get at the end?","options":["He passed his test","Someone found his wallet","He got a new phone"],"answer":1,"why":"اتصلت شركة القطار: Someone found my wallet!"},{"q":"\"When it rains, it pours\" means:","options":["Bad things often happen together","It is raining very hard","Summer is coming"],"answer":0,"why":"المعنى: المصائب لا تأتي فرادى."},{"q":"\"Hang in there\" means:","options":["Hold the rope","Wait outside","Don't give up"],"answer":2,"why":"Hang in there تعني اصبر ولا تستسلم."}],"post":["Tell me about a day when everything went wrong.","What do you say to cheer up a friend?","How do you look on the bright side when things are hard?"],"tip":"لتواسي صديقاً قل: Hang in there. ثم ذكّره بالخير: Look on the bright side... فالكلمة الطيبة تخفّف كثيراً."},{"n":25,"week":45,"title":"Hearing Bad News","group":5,"level":"B1","setting":"Khalid meets Jake and learns that Jake's grandfather is in the hospital.","setting_ar":"يقابل خالد جيك ويعرف أن جدّ جيك في المستشفى.","speakers":["Jake","Khalid"],"pre":["ماذا تقول بالإنجليزية عندما تسمع خبراً محزناً؟","كيف تعرض المساعدة على صديق يمر بظرف صعب؟"],"idioms":[{"e":"I've been better","m":"I've been better","ar":"لست بخير تماماً","ex":"\"How are you?\" \"I've been better. I have a cold.\""},{"e":"sorry to hear that","m":"sorry to hear that","ar":"يؤسفني سماع ذلك","ex":"You failed the test? I'm sorry to hear that."},{"e":"beside oneself","m":"beside herself","ar":"في غاية القلق أو الانفعال","ex":"She was beside herself when her son was lost."},{"e":"on the road to recovery","m":"on the road to recovery","ar":"في طريقه إلى الشفاء","ex":"After the operation, he's on the road to recovery."},{"e":"No such luck","m":"no such luck","ar":"للأسف لم يحدث ذلك","ex":"I hoped the test was easy, but no such luck."},{"e":"speechless","m":"speechless","ar":"عاجز عن الكلام من الصدمة","ex":"The news left me speechless."},{"e":"That's what friends are for","m":"That's what friends are for","ar":"هذا واجب الأصدقاء","ex":"Thanks for your help! — That's what friends are for."},{"e":"get together","m":"get together","ar":"يلتقي ويجتمع","ex":"Let's get together after the exams."},{"e":"take it one day at a time","m":"Take it one day at a time","ar":"خذ الأمور يوماً بيوم","ex":"Moving is hard. Take it one day at a time."}],"keywords":[],"lines":[["Khalid","Hi, Jake. How are you?"],["Jake","Honestly, I've been better. My grandfather fell and broke his hip last week."],["Khalid","Oh no, I'm so sorry to hear that. How is he now?"],["Jake","He had an operation on Monday. My mom was beside herself with worry."],["Khalid","I can imagine. Is he still in the hospital?"],["Jake","Yes. The doctors say he's on the road to recovery, but it will take a few months."],["Khalid","That's good news, at least. Did you get to visit him?"],["Jake","I hoped to go this weekend, but no such luck. I have two exams."],["Khalid","If there's anything I can do, just tell me. I can help you study."],["Jake","Thanks, Khalid. That means a lot. When I told some friends, they were speechless. You're the first to offer help."],["Khalid","That's what friends are for. I'll pray for his recovery."],["Jake","Thank you. Let's get together after my exams. I'll tell you how he's doing."],["Khalid","Sounds good. Take it one day at a time."]],"quiz":[{"q":"What happened to Jake's grandfather?","options":["He had a car accident","He fell and broke his hip","He got the flu"],"answer":1,"why":"قال جيك: My grandfather fell and broke his hip."},{"q":"Why can't Jake visit this weekend?","options":["He has two exams","He has no car","The hospital is closed"],"answer":0,"why":"قال: I have two exams."},{"q":"What did Khalid offer?","options":["To drive Jake to the hospital","To lend him money","To help Jake study"],"answer":2,"why":"قال خالد: I can help you study."},{"q":"\"I've been better\" means:","options":["I'm great","I'm not doing well","I'm better now"],"answer":1,"why":"I've been better تعني لست بخير تماماً."},{"q":"\"on the road to recovery\" means:","options":["getting better","driving to the hospital","still very sick"],"answer":0,"why":"on the road to recovery تعني في طريقه إلى الشفاء."}],"post":["What do you say when a friend tells you bad news?","How can you help a friend who is going through a hard time?","Who do you talk to when you have a problem?"],"tip":"عندما تسمع خبراً محزناً قل: I'm so sorry to hear that. ثم اعرض المساعدة: If there's anything I can do, just tell me."}];
